package dev.danielc.fujiapp;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import android.graphics.*;
import android.net.Uri;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class FrameBatchTest {
 @Test public void createDeduplicatesSourcesAndCopiesSettings()throws Exception{PhotoFrame.Options o=new PhotoFrame.Options();o.style=68;o.title="Trip";JSONObject job=FrameBatch.create(Arrays.asList(Uri.parse("content://a/1"),Uri.parse("content://a/1"),Uri.parse("content://a/2")),o,2,1);o.title="Changed";assertEquals(2,job.getJSONArray("items").length());assertEquals("Trip",job.getJSONObject("options").getString("title"));assertEquals(2,job.getJSONObject("options").getInt("quality"));assertEquals(1,job.getInt("titlePolicy"));}
 @Test public void rejectsCollagesAndTooManyPhotos()throws Exception{PhotoFrame.Options o=new PhotoFrame.Options();o.style=55;try{FrameBatch.create(Arrays.asList(Uri.parse("content://a/1")),o,1,0);fail();}catch(IllegalArgumentException expected){}o.style=0;List<Uri> uris=new ArrayList<>();for(int i=0;i<31;i++)uris.add(Uri.parse("content://a/"+i));try{FrameBatch.create(uris,o,1,0);fail();}catch(IllegalArgumentException expected){}}
 @Test public void retriesNeverReexportSuccessfulItems(){assertFalse(FrameBatch.shouldProcess("done",true));assertFalse(FrameBatch.shouldProcess("done",false));assertFalse(FrameBatch.shouldProcess("failed",false));assertTrue(FrameBatch.shouldProcess("failed",true));assertTrue(FrameBatch.shouldProcess("pending",false));assertFalse(FrameBatch.shouldProcess("pending",true));}
 @Test public void journalRestoresProgressWithoutDiscardingFailures()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();JSONObject r=FrameBatch.create(Arrays.asList(Uri.parse("content://a/1"),Uri.parse("content://a/2")),new PhotoFrame.Options(),1,0);r.getJSONArray("items").getJSONObject(0).put("state","done").put("output","content://saved/1");r.getJSONArray("items").getJSONObject(1).put("state","failed").put("error","unavailable");FrameBatch.open(c,r).persist();JSONObject restored=FrameBatch.list(c).get(0);assertEquals("content://saved/1",restored.getJSONArray("items").getJSONObject(0).getString("output"));assertEquals("failed",restored.getJSONArray("items").getJSONObject(1).getString("state"));}
 @Test public void realExportKeepsSuccessWhenAnotherSourceFailsAndRetrySkipsSuccess()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();File original=new File(c.getFilesDir(),"batch-source.jpg");Bitmap b=Bitmap.createBitmap(120,80,Bitmap.Config.ARGB_8888);b.eraseColor(Color.RED);try(OutputStream out=new FileOutputStream(original)){b.compress(Bitmap.CompressFormat.JPEG,95,out);}b.recycle();JSONObject r=FrameBatch.create(Arrays.asList(Uri.fromFile(original),Uri.fromFile(new File(c.getFilesDir(),"missing.jpg"))),new PhotoFrame.Options(),0,0);FrameBatch batch=FrameBatch.open(c,r);assertTrue(batch.start(false));FrameBatch.WORK.submit(()->{}).get(30,TimeUnit.SECONDS);JSONObject first=batch.snapshot();assertEquals("done",first.getJSONArray("items").getJSONObject(0).getString("state"));String output=first.getJSONArray("items").getJSONObject(0).getString("output");assertTrue(new File(output).isFile());assertEquals("failed",first.getJSONArray("items").getJSONObject(1).getString("state"));assertTrue(batch.start(true));FrameBatch.WORK.submit(()->{}).get(30,TimeUnit.SECONDS);assertEquals(output,batch.snapshot().getJSONArray("items").getJSONObject(0).getString("output"));assertTrue(original.isFile());}
 @Test public void cancelBeforeFirstItemPreservesPendingItemsForResume()throws Exception{java.util.concurrent.CountDownLatch gate=new java.util.concurrent.CountDownLatch(1);FrameBatch.WORK.execute(()->{try{gate.await(10,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}});FrameBatch job=FrameBatch.open(RuntimeEnvironment.getApplication(),FrameBatch.create(Arrays.asList(Uri.parse("content://missing/1")),new PhotoFrame.Options(),0,0));try{assertTrue(job.start(false));assertFalse(job.start(false));job.cancel();}finally{gate.countDown();}FrameBatch.WORK.submit(()->{}).get(30,TimeUnit.SECONDS);assertEquals("pending",job.snapshot().getJSONArray("items").getJSONObject(0).getString("state"));assertTrue(job.hasWork(false));assertFalse(job.running());}
}
